def second_largest(xs):
    # Set to store distinct values
    distinct_values = set()

    # Check if there are enough distinct values
    if len(xs) < 2:
        return None

    # Find distinct values in the list
    for x in xs:
        if x > min(distinct_values) and x not in distinct_values:
            distinct_values.add(x)

    # Return the second largest value if there are more than one, otherwise return None
    if len(distinct_values) > 1:
        return max(distinct_values) - min(distinct_values)
    else:
        return None
